// Every dot is a 2px block with a 1px gap, so the icon renders at a whole-pixel size (21px, or 14px in size-3 slots) and never blurs on 1x screens.
function dotIcon(dots: [number, number][]) {
  return function DotIcon({
    className,
    strokeWidth: _strokeWidth,
    style,
    ...props
  }: PixelIconProps) {
    const px = /(^|\s)size-3(\.5)?(\s|$)/.test(className ?? "") ? 14 : 21;
    return (
      <svg
        className={className}
        fill="currentColor"
        height={px}
        shapeRendering="crispEdges"
        style={{ ...style, flexShrink: 0, height: px, width: px }}
        viewBox="0 0 21 21"
        width={px}
        xmlns="http://www.w3.org/2000/svg"
        {...props}
      >
        {dots.map(([x, y]) => (
          <rect height={2} key={`${x}-${y}`} width={2} x={x * 3} y={y * 3} />
        ))}
      </svg>
    );
  };
}

